parameters.jsCode:
// Get current item
const item = $input.item.json;

// Default output values
const defaultOutput = {
  title: '',
  description: '',
  headings: [],
  content: []
};

// Helper function to clean extracted text
function cleanText(text) {
  if (!text) return '';

  return text
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

try {

  // Validate HTML
  if (!item.data || typeof item.data !== 'string') {
    return {
      ...item,
      ...defaultOutput
    };
  }

  // Limit HTML size for performance
  const html = item.data.substring(0, 80000);

  // -----------------------------
  // Extract Title
  // -----------------------------
  const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);

  const title = titleMatch
    ? cleanText(titleMatch[1])
    : '';

  // -----------------------------
  // Extract Meta Description
  // -----------------------------
  const descMatch =
    html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)/i) ||
    html.match(/<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description/i);

  const description = descMatch
    ? cleanText(descMatch[1])
    : '';

  // -----------------------------
  // Extract H1/H2/H3
  // -----------------------------
  const headingMatches =
    html.match(/<h[1-3][^>]*>[\s\S]*?<\/h[1-3]>/gi) || [];

  const headings = headingMatches
    .map(h => cleanText(h))
    .filter(h => h.length > 2)
    .slice(0, 5);

  // -----------------------------
  // Extract Paragraphs
  // -----------------------------
  const paraMatches =
    html.match(/<p[^>]*>[\s\S]*?<\/p>/gi) || [];

  const content = paraMatches
    .map(p => cleanText(p))
    .filter(p => p.length >= 20 && p.length <= 500)
    .slice(0, 8);

  // -----------------------------
  // Return enriched item
  // -----------------------------
  return {
    ...item,
    title,
    description,
    headings,
    content
  };

} catch (error) {

  return {
    ...item,
    ...defaultOutput,
    parseError: error.message
  };

}

