const payload = $json.body ?? $json;
const requestId = payload.request_id;
const leads = Array.isArray(payload.leads) ? payload.leads : [];

return leads.map((lead) => ({
  json: {
    ...lead,
    request_id: requestId,
    "Lead ID": lead.lead_id ?? lead["Lead ID"] ?? lead.email,
    "Company Name": lead.company_name ?? lead["Company Name"] ?? "",
    "Contact Name": lead.contact_name ?? lead["Contact Name"] ?? "",
    "Designation": lead.job_title ?? lead.Designation ?? "",
    "Email": lead.email ?? lead["Email"] ?? "",
    "Website": lead.website ?? lead["Website"] ?? "",
    "Industry": lead.industry ?? lead["Industry"] ?? "",
  },
}));
